// ── 6. Ensamblado, PDF e integridad ─────────────────────────────────────────
function aPDF(docx) {
  const wrapper = '/mnt/skills/public/docx/scripts/office/soffice.py', a = ['--headless', '--convert-to', 'pdf', '--outdir', outDir, docx], pdf = path.join(outDir, path.basename(docx).replace(/\.docx$/i, '.pdf'));
  for (let i = 1; i <= 3; i++) {
    try { if (fs.existsSync(pdf)) fs.unlinkSync(pdf); } catch (e) {}
    try { if (fs.existsSync(wrapper)) cp.execFileSync('python3', [wrapper, ...a], { stdio: 'ignore', timeout: 240000 }); else cp.execFileSync('soffice', a, { stdio: 'ignore', timeout: 240000 }); } catch (e) {}
    if (fs.existsSync(pdf) && fs.statSync(pdf).size > 500) return pdf;
    try { cp.execSync('pkill -x soffice.bin || true', { stdio: 'ignore' }); } catch (e) {} cp.execSync('sleep 2');
  }
  return null;
}
function integridad(pdf) {                                        // todo el texto de la planeación debe verse en el PDF
  let t = ''; try { t = cp.execFileSync('pdftotext', ['-raw', pdf, '-'], { encoding: 'utf8' }).replace(/\s+/g, ' '); } catch (e) { return null; }
  const ult = (s) => String(s || '').replace(/\*+/g, '').replace(/\s+/g, ' ').trim().split(' ').slice(-2).join(' '), esp = [];
  SEM.forEach(s => { [s.meta, s.inicio, s.desarrollo, s.cierre, s.evaluacion, s.compromiso, s.recursos, s.saber.pregunta, ...s.saber.opciones].forEach(x => esp.push(ult(x))); });
  [F1.meta, F1.pregunta, F3.logro, ...(F3.bibliografia || [])].forEach(x => esp.push(ult(x)));
  const faltan = esp.filter(x => x.length > 3 && !t.includes(x)); return { total: esp.length, faltan };
}
